INSERT INTO `alert_events` VALUES
(10,5,'state_change',NULL,'moi',NULL,'trung_binh',NULL,NULL,NULL,'Sinh tự động theo quy tắc #1',NULL,'2026-10-13 23:34:43'),
(11,5,'state_change','moi','da_review','trung_binh','trung_binh',NULL,NULL,NULL,'Cảnh báo A103-DIEN kỳ 12/2026 ghi nhận mức tiêu thụ 310 kWh, tăng 70,64% so với baseline 181,67 kWh, vượt ngưỡng cho phép 30%. Đề nghị bộ phận Kỹ thuật kiểm tra thực tế chỉ số công tơ, tình trạng thiết bị và xác minh nguyên nhân tăng tiêu thụ trước khi đưa ra kết luận xử lý.',1,'2026-10-13 23:37:34'),
(12,5,'state_change','da_review','can_kiem_tra_lai',NULL,NULL,NULL,NULL,NULL,'Yêu cầu kiểm tra #2: Yêu cầu bộ phận Kỹ thuật kiểm tra lại công tơ A103-DIEN kỳ 12/2026 do tiêu thụ điện đạt 310 kWh, tăng 70,64% so với baseline 181,67 kWh, vượt ngưỡng cảnh báo 30%.\r\n\r\nCần đối chiếu chỉ số đầu và cuối, kiểm tra tình trạng công tơ, xác minh số liệu ghi nhận và nguyên nhân tăng tiêu thụ. Báo cáo kết quả để Ban quản lý xem xét trước khi kết luận và đóng cảnh báo.',1,'2026-10-13 23:39:17'),
(13,5,'state_change','can_kiem_tra_lai','can_kiem_tra_lai',NULL,NULL,NULL,NULL,NULL,'Kết quả kiểm tra #2: Cảnh báo đúng — Đã đối chiếu dữ liệu công tơ A103-DIEN kỳ 12/2026. Chỉ số ghi nhận trên hệ thống phù hợp với kịch bản kiểm tra; mức tiêu thụ 310 kWh được giữ nguyên.\r\n\r\nGiả định công tơ hoạt động bình thường, không phát hiện sai lệch chỉ số. Mức tiêu thụ tăng có thể xuất phát từ nhu cầu sử dụng điện cao hơn các kỳ trước.\r\n\r\nĐề nghị Ban quản lý tiếp tục theo dõi tiêu thụ, xem xét thông báo cư dân sử dụng điện tiết kiệm. Không đề xuất điều chỉnh chỉ số.',2,'2026-10-13 23:43:07'),
(14,5,'state_change','can_kiem_tra_lai','da_xac_nhan',NULL,NULL,NULL,NULL,NULL,'Xác nhận dữ liệu đúng: Ban quản lý đã xem xét kết quả kiểm tra lại Case #2 do Trần Văn Kỹ thực hiện đối với công tơ A103-DIEN, kỳ 12/2026.\r\n\r\nTheo kết quả kiểm tra mô phỏng, chỉ số ghi nhận phù hợp, không phát hiện sai lệch cần điều chỉnh. Xác nhận giữ nguyên dữ liệu tiêu thụ 310 kWh.\r\n\r\nCảnh báo tăng 70,64% so với baseline 181,67 kWh là hợp lệ. Đề nghị tiếp tục theo dõi mức tiêu thụ và đưa ra khuyến nghị sử dụng điện tiết kiệm cho căn hộ A103.',1,'2026-10-13 23:46:58'),
(15,5,'state_change','da_xac_nhan','da_dong',NULL,NULL,NULL,NULL,NULL,'Đã hoàn tất quy trình kiểm tra và xác minh cảnh báo tiêu thụ điện bất thường của căn hộ A103, kỳ 12/2026.\r\n\r\nKỹ thuật đã gửi kết quả kiểm tra Case #2, xác nhận cảnh báo đúng. Ban quản lý đã xác nhận dữ liệu tiêu thụ 310 kWh và giữ nguyên chỉ số công tơ.\r\n\r\nHệ thống DSS đã sinh khuyến nghị theo dõi sau xác minh, bao gồm thông báo cư dân, tìm hiểu nguyên nhân tiêu thụ tăng và hướng dẫn tiết kiệm điện. Các biện pháp này được ghi nhận là đề xuất, chưa xác nhận đã thực hiện.',1,'2026-10-14 00:47:38');
