CREATE TABLE `alerts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `alert_type` varchar(40) NOT NULL DEFAULT 'threshold' COMMENT 'threshold = FN-07 (rule / th??? c??ng); no_usage_consumption = [BA Proposal J-16] (patch 005)',
  `alert_rule_id` int(10) unsigned DEFAULT NULL COMMENT 'NULL n???u c???nh b??o th??? c??ng (FN-07.03)',
  `meter_id` int(10) unsigned DEFAULT NULL,
  `dedupe_meter_id` int(10) unsigned GENERATED ALWAYS AS (coalesce(`meter_id`,0)) STORED COMMENT 'C???t sinh cho kho?? ch???ng tr??ng: 0 = c???nh b??o c???p c??n h??? (kh??ng g???n c??ng t??)',
  `apartment_id` int(10) unsigned NOT NULL,
  `billing_period_id` int(10) unsigned NOT NULL,
  `utility_type` enum('dien','nuoc') DEFAULT NULL COMMENT 'B???t bu???c v???i FN-07; NULL ch??? h???p l??? khi alert_type = no_usage_consumption v?? ngh??a l?? ??i???n + N?????c (patch 005)',
  `source` enum('rule','thu_cong','he_thong') NOT NULL DEFAULT 'rule' COMMENT '[TL] 2.3 Alert: KT Create; he_thong = quy t???c h??? th???ng J-16 (patch 005)',
  `actual_value` decimal(14,4) DEFAULT NULL,
  `compare_value` decimal(14,4) DEFAULT NULL COMMENT 'Gi?? tr??? k??? tr?????c/baseline d??ng ????? so s??nh',
  `percent_change` decimal(8,2) DEFAULT NULL COMMENT '[TL] BR-27',
  `priority` enum('cao','trung_binh','thap') NOT NULL DEFAULT 'trung_binh' COMMENT '[DX] BR-43, BQL c?? th??? s???a',
  `status` enum('moi','da_review','can_kiem_tra_lai','da_xac_nhan','da_dong') NOT NULL DEFAULT 'moi' COMMENT '[ASSUMPTION A-02 - J-04]',
  `description` varchar(500) DEFAULT NULL COMMENT 'M?? t??? hi???n t?????ng khi source=thu_cong (b???t bu???c theo VAL)',
  `snapshot_json` longtext DEFAULT NULL COMMENT 'J-16: d??? li???u l??c ph??t hi???n / ????nh gi?? l???i (CL, c??ng t??, ch??? s???, rule, th???i ??i???m)',
  `created_by` int(10) unsigned DEFAULT NULL COMMENT 'NULL = SYS-01 t??? sinh',
  `reviewed_by` int(10) unsigned DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `closed_by` int(10) unsigned DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `close_reason` varchar(500) DEFAULT NULL,
  `reopen_reason` varchar(500) DEFAULT NULL,
  `conclusion` varchar(40) DEFAULT NULL COMMENT 'J-16 k???t lu???n BQL: apartment_status_incorrect / reading_incorrect / real_consumption_confirmed / undetermined',
  `conclusion_note` varchar(500) DEFAULT NULL,
  `concluded_by` int(10) unsigned DEFAULT NULL,
  `concluded_at` datetime DEFAULT NULL,
  `follow_up_date` date DEFAULT NULL COMMENT 'J-16 k???t lu???n undetermined: ng??y theo d??i l???i',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
