  `system_dedupe_key` tinyint(3) unsigned GENERATED ALWAYS AS (if(`source` = 'he_thong',1,NULL)) STORED COMMENT 'Ch??? kh??c NULL v???i c???nh b??o h??? th???ng -> uq_alert_system_dedupe ch??? ??p cho lo???i n??y',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_alert_dedupe` (`alert_rule_id`,`apartment_id`,`dedupe_meter_id`,`billing_period_id`) COMMENT '[DX] BR-40 kh??ng sinh tr??ng c???nh b??o rule/c??n h???/c??ng t??/k???; alert_rule_id NULL (th??? c??ng) kh??ng b??? ch???n',
  UNIQUE KEY `uq_alert_system_dedupe` (`alert_type`,`apartment_id`,`billing_period_id`,`system_dedupe_key`) COMMENT '[BA Proposal J-16] 1 c???nh b??o h??? th???ng / (lo???i, c??n, k???); ph??t hi???n l???i -> c???p nh???t snapshot / m??? l???i, kh??ng t???o m???i',
  KEY `fk_alert_meter` (`meter_id`),
