  KEY `fk_alert_concluder` (`concluded_by`),
  KEY `idx_alert_type_status` (`alert_type`,`status`),
  CONSTRAINT `fk_alert_apartment` FOREIGN KEY (`apartment_id`) REFERENCES `apartments` (`id`),
  CONSTRAINT `fk_alert_closer` FOREIGN KEY (`closed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
