INSERT INTO `alerts` VALUES
(5,'threshold',1,44,44,20,17,'dien','rule',310.0000,181.6700,70.64,'trung_binh','da_dong','Tiêu thụ điện kỳ 12/2026 của công tơ A103-DIEN thay đổi +70,64% so với baseline (181,67 → 310 kWh), thỏa điều kiện \"Tiêu thụ điện thay đổi > 30% so với baseline\" của quy tắc #1 «Electricity consumption exceeds baseline by more than 30%». Cần xem xét — không phải kết luận sự cố.',NULL,NULL,1,'2026-10-13 23:37:34',1,'2026-10-14 00:47:38','Đã hoàn tất quy trình kiểm tra và xác minh cảnh báo tiêu thụ điện bất thường của căn hộ A103, kỳ 12/2026.\r\n\r\nKỹ thuật đã gửi kết quả kiểm tra Case #2, xác nhận cảnh báo đúng. Ban quản lý đã xác nhận dữ liệu tiêu thụ 310 kWh và giữ nguyên chỉ số công tơ.\r\n\r\nHệ thống DSS đã sinh khuyến nghị theo dõi sau xác minh, bao gồm thông báo cư dân, tìm hiểu nguyên nhân tiêu thụ tăng và hướng dẫn tiết kiệm điện. Các biện pháp này được ghi nhận là đề xuất, chưa xác nhận đã thực hiện.',NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-13 23:34:43','2026-10-14 00:47:38',NULL);
