  `status` enum('da_tinh','da_xac_nhan','bi_tra_lai','da_duyet','da_phat_hanh') NOT NULL DEFAULT 'da_tinh' COMMENT '[ASSUMPTION A-13 - J-18]',
  `confirmed_by` int(10) unsigned DEFAULT NULL COMMENT 'K??? to??n (FN-05.06)',
