(808,1,'CREATE_ALERT_AUTO','alert','5',NULL,'{\"alert_rule_id\":1,\"meter_id\":44,\"apartment_id\":20,\"billing_period_id\":17,\"utility_type\":\"dien\",\"source\":\"rule\",\"actual_value\":\"310.00\",\"compare_value\":\"181.67\",\"percent_change\":\"70.64\",\"priority\":\"trung_binh\",\"status\":\"moi\",\"description\":\"Tiêu thụ điện kỳ 12\\/2026 của công tơ A103-DIEN thay đổi +70,64% so với baseline (181,67 → 310 kWh), thỏa điều kiện \\\"Tiêu thụ điện thay đổi > 30% so với baseline\\\" của quy tắc #1 «Electricity consumption exceeds baseline by more than 30%». Cần xem xét — không phải kết luận sự cố.\",\"created_by\":null,\"rule_snapshot\":{\"id\":1,\"name\":\"Electricity consumption exceeds baseline by more than 30%\",\"measure_type\":\"tieu_thu\",\"utility_type\":\"dien\",\"compare_base\":\"baseline\",\"operator\":\"gt\",\"threshold_value\":\"30.0000\",\"scope_type\":\"toan_toa\",\"scope_value\":null,\"priority_level\":\"trung_binh\",\"updated_at\":\"2026-10-06 19:54:13\"},\"comparison\":{\"scope_type\":\"meter\",\"scope_id\":44,\"utility_type\":\"dien\",\"period_id\":17,\"period_code\":\"12\\/2026\",\"data_status\":\"ok\",\"current_value\":\"310.00\",\"previous_period_code\":\"11\\/2026\",\"previous_status\":\"ok\",\"previous_value\":\"186.00\",\"baseline_id\":24,\"baseline_method\":\"trung_binh_n_ky\",\"baseline_effective_date\":\"2026-12-01\",\"baseline_value\":\"181.67\",\"difference\":\"128.33\",\"percentage_change\":\"70.64\",\"previous_difference\":\"124.00\",\"previous_percentage_change\":\"66.67\",\"trend\":\"up\",\"message\":null}}','::1','2026-10-13 23:34:43'),
