(811,1,'REVIEW_ALERT','alert','5','{\"status\":\"moi\",\"priority\":\"trung_binh\"}','{\"status\":\"da_review\",\"priority\":\"trung_binh\",\"reviewed_at\":\"2026-10-13 23:37:34\",\"note\":\"Cảnh báo A103-DIEN kỳ 12\\/2026 ghi nhận mức tiêu thụ 310 kWh, tăng 70,64% so với baseline 181,67 kWh, vượt ngưỡng cho phép 30%. Đề nghị bộ phận Kỹ thuật kiểm tra thực tế chỉ số công tơ, tình trạng thiết bị và xác minh nguyên nhân tăng tiêu thụ trước khi đưa ra kết luận xử lý.\"}','::1','2026-10-13 23:37:34'),
(812,1,'REQUEST_ALERT_VERIFICATION','alert','5','{\"status\":\"da_review\"}','{\"status\":\"can_kiem_tra_lai\",\"case_id\":2,\"assigned_to\":2,\"content\":\"Yêu cầu bộ phận Kỹ thuật kiểm tra lại công tơ A103-DIEN kỳ 12\\/2026 do tiêu thụ điện đạt 310 kWh, tăng 70,64% so với baseline 181,67 kWh, vượt ngưỡng cảnh báo 30%.\\r\\n\\r\\nCần đối chiếu chỉ số đầu và cuối, kiểm tra tình trạng công tơ, xác minh số liệu ghi nhận và nguyên nhân tăng tiêu thụ. Báo cáo kết quả để Ban quản lý xem xét trước khi kết luận và đóng cảnh báo.\"}','::1','2026-10-13 23:39:17'),
