(818,1,'CONFIRM_ALERT_DATA','alert','5','{\"status\":\"can_kiem_tra_lai\",\"case_status\":\"da_co_ket_qua\"}','{\"status\":\"da_xac_nhan\",\"decision\":\"confirm\",\"note\":\"Ban quản lý đã xem xét kết quả kiểm tra lại Case #2 do Trần Văn Kỹ thực hiện đối với công tơ A103-DIEN, kỳ 12\\/2026.\\r\\n\\r\\nTheo kết quả kiểm tra mô phỏng, chỉ số ghi nhận phù hợp, không phát hiện sai lệch cần điều chỉnh. Xác nhận giữ nguyên dữ liệu tiêu thụ 310 kWh.\\r\\n\\r\\nCảnh báo tăng 70,64% so với baseline 181,67 kWh là hợp lệ. Đề nghị tiếp tục theo dõi mức tiêu thụ và đưa ra khuyến nghị sử dụng điện tiết kiệm cho căn hộ A103.\",\"adjusted\":null,\"case_id\":2}','::1','2026-10-13 23:46:58'),
