CREATE TABLE `baselines` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `scope_type` enum('meter','apartment','zone','building') NOT NULL,
  `scope_id` int(10) unsigned NOT NULL COMMENT 'Id th???c th??? theo scope_type: meters/apartments/zones/buildings.id. ??a h??nh -> kh??ng FK, Service ki???m tra t???n t???i',
  `utility_type` enum('dien','nuoc') NOT NULL,
  `method` enum('ky_truoc','trung_binh_n_ky','cung_ky_nam_truoc','nhap_tay') NOT NULL DEFAULT 'trung_binh_n_ky' COMMENT '[ASSUMPTION A-08 - J-20]',
  `n_periods` tinyint(3) unsigned DEFAULT 3 COMMENT '[TL] T2 c??u 25: t???i thi???u 3 k???',
  `manual_value` decimal(12,2) DEFAULT NULL,
  `computed_value` decimal(12,2) DEFAULT NULL COMMENT 'Gi?? tr??? baseline t??nh ???????c, cache l???i ????? truy v???n nhanh',
  `effective_date` date NOT NULL,
  `status` enum('hieu_luc','het_hieu_luc') NOT NULL DEFAULT 'hieu_luc',
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_baseline_creator` (`created_by`),
  KEY `idx_baseline_scope` (`scope_type`,`scope_id`,`utility_type`,`status`),
  CONSTRAINT `fk_baseline_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
