INSERT INTO `billing_adjustment_requests` VALUES
(1,21,3,'approved','2026-11-01','Đề nghị bổ sung phí gửi xe cho căn TEST-01, kỳ 11/2026. Bản tính gốc #21 đã được xác nhận trước khi cập nhật phương tiện. Căn hộ có 2 xe đạp điện và 1 xe máy, áp dụng cho toàn kỳ 11/2026, phát sinh khoản phụ thu 250.000 đồng. Đề nghị Ban quản lý phê duyệt chứng từ phụ thu riêng, không thay đổi bản tính và email thông báo đã phát hành.','Dữ liệu mô phỏng phục vụ demo Energy DSS. Tham chiếu: danh sách phương tiện của căn TEST-01 gồm 2 xe đạp điện và 1 xe máy; biểu giá gửi xe phiên bản #8 (100.000 đồng/xe đạp điện) và #9 (50.000 đồng/xe máy). Quyết định nghiệp vụ mô phỏng: áp dụng toàn kỳ từ 01/11/2026. Khoản phụ thu đề nghị: 250.000 đồng.',250000.00,'1158edb2d542521b0c050022e0cbc48830e1da26b3c3910773c72924dad1e544','{\"charge\":{\"id\":21,\"apartment_id\":17,\"billing_period_id\":12,\"electricity_consumption\":\"160.00\",\"electricity_amount\":\"313620.00\",\"electricity_vat_amount\":\"25089.60\",\"water_consumption\":\"10.00\",\"water_amount\":\"110450.00\",\"service_fee_amount\":\"240000.00\",\"fire_insurance_amount\":\"156240.00\",\"parking_fee_amount\":\"0.00\",\"total_arising\":\"845399.60\",\"old_debt_amount\":\"0.00\",\"total_due\":\"845399.60\",\"status\":\"da_xac_nhan\",\"confirmed_by\":3,\"confirmed_at\":\"2026-10-12 19:14:11\",\"approved_by\":null,\"approved_at\":null,\"rejection_reason\":null,\"issued_at\":null,\"created_at\":\"2026-10-12 19:14:00\",\"updated_at\":\"2026-10-12 19:14:11\"},\"period\":{\"id\":12,\"period_code\":\"11\\/2026\",\"start_date\":\"2026-11-01\",\"end_date\":\"2026-11-30\"},\"original_audit_id\":269,\"original_audit_hash\":\"31939bc890103b6a3f15048cb14dab49db934e7243f3bc4f516192fc63c781ac\",\"notices\":[{\"id\":1,\"status\":\"sent\",\"content_hash\":\"36b8499301267365cfe239b2d4d7d59a6629c5cd4f023678d6bf2d1fde15ed24\",\"sent_at\":\"2026-10-12 19:51:05\",\"body_hash\":\"36b8499301267365cfe239b2d4d7d59a6629c5cd4f023678d6bf2d1fde15ed24\"}],\"tiers\":[{\"meter_reading_id\":216,\"utility_type\":\"dien\",\"tier_order\":1,\"tier_from\":\"0.00\",\"tier_to\":\"50.00\",\"quantity\":\"50.00\",\"unit_price\":\"1806.00\",\"amount\":\"90300.00\"},{\"meter_reading_id\":216,\"utility_type\":\"dien\",\"tier_order\":2,\"tier_from\":\"50.00\",\"tier_to\":\"100.00\",\"quantity\":\"50.00\",\"unit_price\":\"1866.00\",\"amount\":\"93300.00\"},{\"meter_reading_id\":216,\"utility_type\":\"dien\",\"tier_order\":3,\"tier_from\":\"100.00\",\"tier_to\":\"200.00\",\"quantity\":\"60.00\",\"unit_price\":\"2167.00\",\"amount\":\"130020.00\"},{\"meter_reading_id\":217,\"utility_type\":\"nuoc\",\"tier_order\":1,\"tier_from\":\"0.00\",\"tier_to\":\"10.00\",\"quantity\":\"10.00\",\"unit_price\":\"11045.00\",\"amount\":\"110450.00\"}],\"readings\":[{\"id\":216,\"meter_id\":37,\"billing_period_id\":12,\"previous_reading\":\"200.00\",\"current_reading\":\"360.00\",\"consumption\":\"160.00\",\"status\":\"da_xac_nhan\",\"source\":\"dieu_chinh\",\"import_batch_id\":null,\"is_meter_changed\":0,\"old_meter_id\":null,\"note\":\"Đọc lại và đối chiếu chỉ số, sửa 380 thành 360.\",\"entered_by\":2,\"confirmed_by\":1,\"confirmed_at\":\"2026-10-12 18:27:11\",\"created_at\":\"2026-10-12 18:09:29\",\"updated_at\":\"2026-10-12 18:27:11\",\"needs_correction\":0,\"correction_reason\":\"Xác minh lại chỉ số 360 trước khi duyệt.\",\"returned_by\":1,\"returned_at\":\"2026-10-12 18:22:34\",\"utility_type\":\"dien\",\"usage_type\":\"sinh_hoat\",\"meter_status\":\"hoat_dong\"},{\"id\":217,\"meter_id\":38,\"billing_period_id\":12,\"previous_reading\":\"20.00\",\"current_reading\":\"30.00\",\"consumption\":\"10.00\",\"status\":\"da_xac_nhan\",\"source\":\"thu_cong\",\"import_batch_id\":null,\"is_meter_changed\":0,\"old_meter_id\":null,\"note\":\"Nhập chỉ số nước để kiểm thử quy trình duyệt.\",\"entered_by\":2,\"confirmed_by\":1,\"confirmed_at\":\"2026-10-12 18:28:32\",\"created_at\":\"2026-10-12 18:10:33\",\"updated_at\":\"2026-10-12 18:28:32\",\"needs_correction\":0,\"correction_reason\":null,\"returned_by\":null,\"returned_a