\"lines\":[{\"tier_order\":1,\"tier_from\":\"0.00\",\"tier_to\":\"10.00\",\"quantity\":\"10.00\",\"unit_price\":\"11045.00\",\"amount\":\"110450.00\"}],\"subtotal\":\"110450.00\",\"vat\":\"0.00\",\"total\":\"110450.00\"}],\"fees\":[{\"group\":\"service\",\"fee_type\":\"dich_vu_co_o\",\"rate_id\":5,\"rate_effective_date\":\"2024-01-01\",\"base_quantity\":\"80.00\",\"base_unit\":\"m²\",\"unit_price\":\"3000.00\",\"amount\":\"240000.00\"},{\"group\":\"fire_insurance\",\"fee_type\":\"bao_hiem_chay_no\",\"rate_id\":7,\"rate_effective_date\":\"2024-01-01\",\"base_quantity\":\"80.00\",\"base_unit\":\"m²\",\"unit_price\":\"1953.00\",\"amount\":\"156240.00\"},{\"group\":\"parking\",\"fee_type\":\"gui_xe_dap_dien\",\"rate_id\":8,\"rate_effective_date\":\"2024-01-01\",\"base_quantity\":\"2.00\",\"base_unit\":\"xe\",\"unit_price\":\"100000.00\",\"amount\":\"200000.00\"},{\"group\":\"parking\",\"fee_type\":\"gui_xe_may\",\"rate_id\":9,\"rate_effective_date\":\"2024-01-01\",\"base_quantity\":\"1.00\",\"base_unit\":\"xe\",\"unit_price\":\"50000.00\",\"amount\":\"50000.00\"}],\"not_calculated\":[{\"fee_type\":\"mo_lai_dich_vu\",\"note\":\"NOT CALCULATED – BLOCKED J-09\\/B11: hệ thống không có sự kiện cắt\\/mở lại dịch vụ và phiếu không có cột lưu khoản này.\"}],\"warnings\":[],\"totals\":{\"utility_charge\":\"449159.60\",\"fixed_fee\":\"646240.00\",\"old_debt\":\"0.00\",\"current_period_total\":\"1095399.60\",\"total_payable\":\"1095399.60\"}},\"amount\":\"250000.00\"}','fa6a1c52a6c3a2a00f84e2ef314b0ad28efda9d76a0282d5fbbc62427a993160',1,'Phê duyệt đề nghị đối soát #1 cho căn TEST-01, kỳ 11/2026. Xác nhận 2 xe đạp điện và 1 xe máy áp dụng toàn kỳ từ 01/11/2026, tổng phụ thu 250.000 đồng theo biểu giá hiện hành. Yêu cầu lập chứng từ ghi nợ bổ sung riêng, giữ nguyên bản tính gốc #21 và email đã phát hành.','2026-10-13 22:12:31','2026-10-13 22:32:18');
