CREATE TABLE `billing_periods` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `period_code` varchar(7) NOT NULL COMMENT '?????nh d???ng MM/YYYY [DX]',
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `reading_due_date` date DEFAULT NULL COMMENT '[DX] ph???c v??? KPI th???i gian x??? l??',
  `status` enum('mo','da_khoa','mo_lai') NOT NULL DEFAULT 'mo',
  `created_by` int(10) unsigned DEFAULT NULL COMMENT '[ASSUMPTION A-05 - J-10]',
  `locked_by` int(10) unsigned DEFAULT NULL,
  `locked_at` datetime DEFAULT NULL,
  `reopened_by` int(10) unsigned DEFAULT NULL COMMENT '[TL] 2.3 ch??? BQL ???????c m??? l???i',
  `reopened_at` datetime DEFAULT NULL,
  `reopen_reason` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_period_code` (`period_code`),
  KEY `fk_period_creator` (`created_by`),
  KEY `fk_period_locker` (`locked_by`),
  KEY `fk_period_reopener` (`reopened_by`),
  KEY `idx_period_status` (`status`),
  CONSTRAINT `fk_period_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_period_locker` FOREIGN KEY (`locked_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_period_reopener` FOREIGN KEY (`reopened_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
