       </tr>\n                            <tr>\n                <td style=\"font-family:\'Segoe UI\',Roboto,\'Helvetica Neue\',Helvetica,Arial,sans-serif;border-top:1px solid #e9edf6;padding:15px 0;font-size:15px;color:#33405e;\">Còn nợ tháng trước</td>\n                <td align=\"right\" style=\"font-family:\'Segoe UI\',Roboto,\'Helvetica Neue\',Helvetica,Arial,sans-serif;border-top:1px solid #e9edf6;padding:15px 0;font-size:15px;white-space:nowrap;color:#0b1f66;font-weight:600;\">0 đ</td>\n              </tr>\n                          </table>\n          </td></tr>\n          <!-- Tổng phải thu: khối lớn full ngang -->\n          <tr><td style=\"padding:14px 18px 18px;\">\n            <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background:#e8effd;background-image:linear-gradient(100deg,#eef3ff 0%,#dfe8fc 100%);border-radius:14px;border-collapse:separate;\">\n              <tr>\n                <td class=\"st-total-label\" style=\"font-family:\'Segoe UI\',Roboto,\'Helvetica Neue\',Helvetica,Arial,sans-serif;padding:26px 26px;font-size:19px;font-weight:700;color:#0b1f66;\">Tổng phải thu</td>\n                <td align=\"right\" style=\"font-family:\'Segoe UI\',Roboto,\'Helvetica Neue\',Helvetica,Arial,sans-serif;padding:26px 26px;white-space:nowrap;\"><span class=\"st-total\" style=\"font-size:40px;line-height:1;font-weight:800;letter-spacing:-1px;color:#0b1f66;\">845.399,6 đ</span></td>\n              </tr>\n            </table>\n          </td></tr>\n        </table>\n      </td></tr>\n\n      <!-- Thanh toán QR: full ngang, QR lớn bên trái, thông tin tài khoản bên phải -->\n      <tr><td class=\"st-pad\" style=\"padding:24px 44px 0;\">\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background:#f2f6ff;border:1px solid #e1e8f6;border-radius:18px;border-collapse:separate;\">\n          <tr>\n            <td class=\"st-col st-qr\" width=\"266\" va