           </tr>\n                <tr>\n                  <td style=\"font-family:\'Segoe UI\',Roboto,\'Helvetica Neue\',Helvetica,Arial,sans-serif;padding:14px 18px;font-size:14px;color:#6b7591;border-bottom:1px solid #e9edf6;\">Số tài khoản</td>\n                  <td align=\"right\" style=\"font-family:\'Segoe UI\',Roboto,\'Helvetica Neue\',Helvetica,Arial,sans-serif;padding:14px 18px;font-size:15px;font-weight:700;letter-spacing:1px;color:#0b1f66;border-bottom:1px solid #e9edf6;\">941*****999</td>\n                </tr>\n                <tr>\n                  <td style=\"font-family:\'Segoe UI\',Roboto,\'Helvetica Neue\',Helvetica,Arial,sans-serif;padding:14px 18px;font-size:14px;color:#6b7591;\">Ngân hàng</td>\n                  <td align=\"right\" style=\"font-family:\'Segoe UI\',Roboto,\'Helvetica Neue\',Helvetica,Arial,sans-serif;padding:14px 18px;color:#0b1f66;\">\n                    <div style=\"font-size:15px;font-weight:800;color:#1f3fbf;\"><span>MB</span></div>\n                    <div style=\"font-size:12px;color:#6b7591;\">Ngân hàng TMCP Quân đội</div>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n        </table>\n      </td></tr>\n\n      <!-- Footer -->\n      <tr><td class=\"st-pad\" style=\"padding:28px 44px 32px;\">\n        <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"border-top:1px solid #e9edf6;\">\n          <tr>\n            <td class=\"st-col\" valign=\"middle\" style=\"font-family:\'Segoe UI\',Roboto,\'Helvetica Neue\',Helvetica,Arial,sans-serif;padding-top:18px;font-size:12px;line-height:1.65;color:#8f99b3;\">\n              Email được gửi tự động từ hệ thống <span style=\"color:#1f3fbf;font-weight:600;\">Energy DSS</span> theo yêu cầu của Ban Quản lý.<br>\n              Vui lòng không trả lời email này. Mọi thắc mắc xin liên hệ Ban Quản lý.\n            </td>\n            <td class=\"st-col\" valign=\"middle\" align=