INSERT INTO `inspection_cases` VALUES
(2,5,'Yêu cầu bộ phận Kỹ thuật kiểm tra lại công tơ A103-DIEN kỳ 12/2026 do tiêu thụ điện đạt 310 kWh, tăng 70,64% so với baseline 181,67 kWh, vượt ngưỡng cảnh báo 30%.\r\n\r\nCần đối chiếu chỉ số đầu và cuối, kiểm tra tình trạng công tơ, xác minh số liệu ghi nhận và nguyên nhân tăng tiêu thụ. Báo cáo kết quả để Ban quản lý xem xét trước khi kết luận và đóng cảnh báo.',2,'da_dong','canh_bao_dung',NULL,'Đã đối chiếu dữ liệu công tơ A103-DIEN kỳ 12/2026. Chỉ số ghi nhận trên hệ thống phù hợp với kịch bản kiểm tra; mức tiêu thụ 310 kWh được giữ nguyên.\r\n\r\nGiả định công tơ hoạt động bình thường, không phát hiện sai lệch chỉ số. Mức tiêu thụ tăng có thể xuất phát từ nhu cầu sử dụng điện cao hơn các kỳ trước.\r\n\r\nĐề nghị Ban quản lý tiếp tục theo dõi tiêu thụ, xem xét thông báo cư dân sử dụng điện tiết kiệm. Không đề xuất điều chỉnh chỉ số.',1,'2026-10-13 23:39:17','2026-10-13 23:46:58');
/*!40000 ALTER TABLE `inspection_cases` ENABLE KEYS */;
UNLOCK TABLES;
