  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_meters_code` (`meter_code`),
  KEY `idx_meters_apartment` (`apartment_id`),
  KEY `idx_meters_status` (`status`),
  CONSTRAINT `fk_meter_apartment` FOREIGN KEY (`apartment_id`) REFERENCES `apartments` (`id`)
