INSERT INTO `recommendation_revisions` VALUES
(1,5,2,4,NULL,'verified_confirm','Theo dõi sau xác minh','Dữ liệu đã được Ban quản lý xác nhận sau kiểm tra. Xem xét thông báo cư dân căn A103, tìm hiểu mức sử dụng điện tăng, hướng dẫn tiết kiệm và theo dõi kỳ tiếp theo. Không yêu cầu kiểm tra lại công tơ khi chưa có lý do mới.','350c21a62d006d6c8d7de5965841aaa7db60861472b4ab39930d32b1622c7bd2','{\"context\":{\"stage\":\"verified_confirm\",\"actionable\":true,\"category\":\"Theo dõi sau xác minh\",\"text\":\"Dữ liệu đã được Ban quản lý xác nhận sau kiểm tra. Xem xét thông báo cư dân căn A103, tìm hiểu mức sử dụng điện tăng, hướng dẫn tiết kiệm và theo dõi kỳ tiếp theo. Không yêu cầu kiểm tra lại công tơ khi chưa có lý do mới.\",\"reason\":\"Case đã đóng, Kỹ thuật xác nhận cảnh báo đúng và Ban quản lý giữ nguyên dữ liệu.\",\"evidence\":{\"alert\":{\"id\":5,\"alert_type\":\"threshold\",\"alert_rule_id\":1,\"meter_id\":44,\"apartment_id\":20,\"billing_period_id\":17,\"utility_type\":\"dien\",\"actual_value\":\"310.0000\",\"compare_value\":\"181.6700\",\"percent_change\":\"70.64\",\"priority\":\"trung_binh\",\"status\":\"da_xac_nhan\",\"conclusion\":null},\"case\":{\"id\":2,\"alert_id\":5,\"content\":\"Yêu cầu bộ phận Kỹ thuật kiểm tra lại công tơ A103-DIEN kỳ 12\\/2026 do tiêu thụ điện đạt 310 kWh, tăng 70,64% so với baseline 181,67 kWh, vượt ngưỡng cảnh báo 30%.\\r\\n\\r\\nCần đối chiếu chỉ số đầu và cuối, kiểm tra tình trạng công tơ, xác minh số liệu ghi nhận và nguyên nhân tăng tiêu thụ. Báo cáo kết quả để Ban quản lý xem xét trước khi kết luận và đóng cảnh báo.\",\"assigned_to\":2,\"status\":\"da_dong\",\"result_conclusion\":\"canh_bao_dung\",\"rechecked_value\":null,\"note\":\"Đã đối chiếu dữ liệu công tơ A103-DIEN kỳ 12\\/2026. Chỉ số ghi nhận trên hệ thống phù hợp với kịch bản kiểm tra; mức tiêu thụ 310 kWh được giữ nguyên.\\r\\n\\r\\nGiả định công tơ hoạt động bình thường, không phát hiện sai lệch chỉ số. Mức tiêu thụ tăng có thể xuất phát từ nhu cầu sử dụng điện cao hơn các kỳ trước.\\r\\n\\r\\nĐề nghị Ban quản lý tiếp tục theo dõi tiêu thụ, xem xét thông báo cư dân sử dụng điện tiết kiệm. Không đề xuất điều chỉnh chỉ số.\",\"created_by\":1,\"created_at\":\"2026-10-13 23:39:17\",\"updated_at\":\"2026-10-13 23:46:58\",\"assigned_to_name\":\"Trần Văn Kỹ\",\"created_by_name\":\"Nguyễn Văn Quản\"},\"decision\":{\"status\":\"da_xac_nhan\",\"decision\":\"confirm\",\"note\":\"Ban quản lý đã xem xét kết quả kiểm tra lại Case #2 do Trần Văn Kỹ thực hiện đối với công tơ A103-DIEN, kỳ 12\\/2026.\\r\\n\\r\\nTheo kết quả kiểm tra mô phỏng, chỉ số ghi nhận phù hợp, không phát hiện sai lệch cần điều chỉnh. Xác nhận giữ nguyên dữ liệu tiêu thụ 310 kWh.\\r\\n\\r\\nCảnh báo tăng 70,64% so với baseline 181,67 kWh là hợp lệ. Đề nghị tiếp tục theo dõi mức tiêu thụ và đưa ra khuyến nghị sử dụng điện tiết kiệm cho căn hộ A103.\",\"adjusted\":null,\"case_id\":2},\"decision_audit_id\":818,\"last_reopen_audit_id\":0,\"threshold_snapshot\":{\"id\":1,\"name\":\"Electricity consumption exceeds baseline by more than 30%\",\"measure_type\":\"tieu_thu\",\"utility_type\":\"dien\",\"compare_base\":\"baseline\",\"operator\":\"gt\",\"threshold_value\":\"30.0000\",\"scope_type\":\"toan_toa\",\"scope_value\":null,\"priority_level\":\"trung_binh\",\"updated_at\":\"2026-10-06 19:54:13\"},\"reading\":{\"id\":320,\"previous_reading\":\"900.00\",\"current_reading\":\"1210.00\",\"consumption\":\"310.00\",\"status\":\"da_xac_nhan\",\"is_meter_changed\":0,\"updated_at\":\"2026-10-13 23:16:33\"}},\"policy_version\":\"fn08-workflow-v1\"},\"rule\":{\"id\":2,\"name\":\"High electricity consumption requires verification\",\"condition_type\":\"vuot_nguong_lien_tiep\",\"condition_params\":\"{\\\"n_periods\\\":1}\",\"recommendation_text\":\"Inspect the electricity meter and verify actual usage conditions before making a final conclusion.\",\"status\":\"bat\",\"created_by\":1,\"created_at\":\"2026-10-04 11:40:19\"},\"match\":{\"matched\":true,\"reason\":\"Vượt ngưỡng quy tắc #1 trong 1 kỳ liên tiếp\",\"evidence\":[{\"period\":\"12\\/2026\",\"alert_rule_id\":1,\"exceeded\":true}]}}',1,'2026-10-14 00:45:04');
