/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `cleanup_demo_keep_112026` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
DELIMITER ;;
CREATE  PROCEDURE `cleanup_demo_keep_112026`(IN `apply_changes` BOOLEAN)
BEGIN
    DECLARE keep_period INT DEFAULT 12;
    DECLARE keep_apartment INT DEFAULT 17;
    DECLARE keep_building INT DEFAULT 5;
    DECLARE keep_zone INT DEFAULT 8;
    DECLARE before_readings INT;
    DECLARE before_charges INT;
    DECLARE before_details INT;
    DECLARE before_payments INT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF DATABASE() <> 'energy_dss' OR apply_changes IS NULL OR apply_changes NOT IN (0,1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Sai database hoac tham so chay.';
    END IF;
    START TRANSACTION;
    IF (SELECT COUNT(*) FROM billing_periods WHERE id=12 AND period_code='11/2026') <> 1
       OR (SELECT COUNT(*) FROM buildings WHERE id=5 AND code='TEST-DSS') <> 1
       OR (SELECT COUNT(*) FROM zones WHERE id=8 AND building_id=5 AND code='ZONE-TEST') <> 1
       OR (SELECT COUNT(*) FROM apartments WHERE id=17 AND building_id=5 AND zone_id=8 AND code='TEST-01') <> 1
       OR (SELECT COUNT(*) FROM meters WHERE apartment_id=17 AND
           ((id=37 AND meter_code='TEST-01-DIEN') OR (id=38 AND meter_code='TEST-01-NUOC'))) <> 2
       OR (SELECT COUNT(*) FROM meter_readings WHERE billing_period_id=12 AND id IN (216,217)) <> 2
       OR (SELECT COUNT(*) FROM apartment_charges WHERE id=21 AND apartment_id=17 AND billing_period_id=12) <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Du lieu khong khop export: dung lai, khong xoa.';
    END IF;

    
    IF EXISTS(SELECT 1 FROM meter_readings r JOIN meters m ON m.id=r.meter_id
              WHERE r.billing_period_id=12 AND m.apartment_id<>17)
       OR EXISTS(SELECT 1 FROM apartment_charges WHERE billing_period_id=12 AND apartment_id<>17)
       OR EXISTS(SELECT 1 FROM alerts WHERE billing_period_id=12 AND apartment_id<>17)
       OR EXISTS(SELECT 1 FROM email_notifications WHERE billing_period_id=12 AND apartment_id<>17) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Ky 11/2026 co du lieu can khac: can ra soat lai.';
    END IF;

    SELECT COUNT(*) INTO before_readings FROM meter_readings WHERE billing_period_id=12;
    SELECT COUNT(*) INTO before_charges FROM apartment_charges WHERE billing_period_id=12;
    SELECT COUNT(*) INTO before_details FROM charge_tier_details d JOIN apartment_charges c
        ON c.id=d.apartment_charge_id WHERE c.billing_period_id=12;
    SELECT COUNT(*) INTO before_payments FROM payment_transactions p JOIN apartment_charges c
        ON c.id=p.apartment_charge_id WHERE c.billing_period_id=12;

    SELECT 'TRUOC KHI DON' AS stage,
        (SELECT COUNT(*) FROM billing_periods) AS periods,
        (SELECT COUNT(*) FROM buildings) AS buildings,
        (SELECT COUNT(*) FROM apartments) AS apartments,
        (SELECT COUNT(*) FROM meters) AS meters,
        (SELECT COUNT(*) FROM meter_readings) AS readings;

    
    DELETE e FROM email_notifications e
    LEFT JOIN apartment_charges c ON c.id=e.apartment_charge_id
    LEFT JOIN alerts a ON a.id=e.alert_id
    WHERE e.apartment_id<>17 OR (e.billing_period_id IS NOT NULL AND e.billing_period_id<>12)
       OR (c.id IS NOT NULL AND c.billing_period_id<>12)
       OR (a.id IS NOT NULL AND (a.billing_period_id<>12 OR a.apartment_id<>17));

    DELETE p FROM payment_transactions p JOIN apartment_charges c ON c.id=p.apartment_charge_id
    WHERE c.billing_period_id<>12 OR c.apartment_id<>17;
    DELETE d FROM charge_tier_details d JOIN apartment_charges c ON c.id=d.apartment_charge_id
    WHERE c.billing_period_id<>12 OR c.apartment_id<>17;
    DELETE FROM apartment_charges WHERE billing_period_id<>12 OR apartment_id<>17;
    DELETE FROM alerts WHERE billing_period_id<>12 OR apartment_id<>17;

    DELETE FROM consumption_targets WHERE billing_period_id<>12 OR NOT
        ((scope_type='apartment' AND scope_id=17) OR (scope_type='zone' AND scope_id=8)
         OR (scope_type='building' AND scope_id=5));
    
    DELETE FROM consumption_forecasts;
    DELETE FROM baselines WHERE NOT
        ((scope_type='meter' AND scope_id IN (37,38)) OR (scope_type='apartment' AND scope_id=17)
         OR (scope_type='zone' AND scope_id=8) OR (scope_type='building' AND scope_id=5));
    DELETE FROM baselines WHERE method<>'nhap_tay';

    DELETE FROM figma_backup_meter_readings WHERE billing_period_id<>12 OR meter_id NOT IN (37,38);
    DELETE FROM meter_readings WHERE billing_period_id<>12;
    DELETE FROM import_batches WHERE billing_period_id<>12;
    

    DELETE FROM parking_vehicles WHERE apartment_id<>17;
    DELETE FROM residents WHERE apartment_id<>17;
    DELETE FROM meters WHERE apartment_id<>17;
    DELETE FROM apartments WHERE id<>17;
    DELETE FROM zones WHERE id<>8;
    DELETE FROM buildings WHERE id<>5;
    DELETE FROM billing_periods WHERE id<>12;

    
    DELETE FROM audit_logs WHERE created_at<'2026-10-12 18:00:32';
    
    

    IF (SELECT COUNT(*) FROM meter_readings WHERE billing_period_id=12)<>before_readings
       OR (SELECT COUNT(*) FROM apartment_charges WHERE billing_period_id=12)<>before_charges
       OR (SELECT COUNT(*) FROM charge_tier_details d JOIN apartment_charges c
           ON c.id=d.apartment_charge_id WHERE c.billing_period_id=12)<>before_details
       OR (SELECT COUNT(*) FROM payment_transactions p JOIN apartment_charges c
           ON c.id=p.apartment_charge_id WHERE c.billing_period_id=12)<>before_payments THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Kiem tra bao toan that bai: da ROLLBACK.';
    END IF;

    SELECT 'SAU KHI DON (TRONG TRANSACTION)' AS stage,
        (SELECT COUNT(*) FROM billing_periods) AS periods,
        (SELECT COUNT(*) FROM buildings) AS buildings,
        (SELECT COUNT(*) FROM zones) AS zones,
        (SELECT COUNT(*) FROM apartments) AS apartments,
        (SELECT COUNT(*) FROM meters) AS meters,
        (SELECT COUNT(*) FROM meter_readings) AS readings,
        (SELECT COUNT(*) FROM apartment_charges) AS charges;
    SELECT id,period_code,status FROM billing_periods;
    SELECT id,meter_id,previous_reading,current_reading,consumption,status
        FROM meter_readings ORDER BY id;
    SELECT id,apartment_id,billing_period_id,status,total_due FROM apartment_charges;

    IF apply_changes=1 THEN
        COMMIT;
        SELECT 'DA XOA THAT VA COMMIT' AS result;
    ELSE
        ROLLBACK;
        SELECT 'CHI CHAY THU - DA ROLLBACK - KHONG XOA DU LIEU' AS result;
    END IF;
END ;;
DELIMITER ;
